<?php require_once __DIR__.'/includes/bootstrap.php'; if(is_logged_in()) redirect('/dashboard.php'); $errors=[]; $name='';$email='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';
if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Enter a name between 2 and 100 characters.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.'; if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';
$s=$pdo->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='That email address is already registered.';
if(!$errors){try{$pic=upload_profile_picture();$s=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,profile_picture) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$pic]);session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();flash('success','Your account has been created. Welcome to EventPro!');redirect('/dashboard.php');}catch(Throwable $ex){$errors[]=$ex instanceof RuntimeException?$ex->getMessage():'Registration failed. Please try again.';}}
}
$page_title='Create account';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><section class="panel form-panel"><h1>Create your account</h1><p class="muted">Join EventPro to manage events and message other members.</p><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Full name<input name="full_name" required minlength="2" maxlength="100" value="<?= e($name) ?>" autocomplete="name"></label><label>Email address<input type="email" name="email" required value="<?= e($email) ?>" autocomplete="email"></label><label>Password<input type="password" name="password" required minlength="8" autocomplete="new-password"><small>Use at least 8 characters.</small></label><label>Profile picture <span class="muted">(optional, JPG/PNG/WEBP, max 2 MB)</span><input type="file" name="profile_picture" accept="image/jpeg,image/png,image/webp" data-image-input></label><img class="image-preview hidden" data-image-preview alt="Profile picture preview"><button class="button primary" type="submit">Create account</button></form><p class="form-foot">Already registered? <a href="login.php">Log in</a></p></section></div><?php require __DIR__.'/includes/footer.php'; ?>